import pathlib,json,shutil,csv
from docx import Document
from openpyxl import Workbook,load_workbook
from openpyxl.styles import Font,PatternFill,Alignment
p=pathlib.Path('/workspace/project-review/outputs/BRRP_P9_Input_Review');inv=json.loads((p/'inventory.json').read_text())
findings=[
('P9-01','Bid security','Corrigendum.pdf p1','Any e-BG must be executed on NeSL before the tender closing deadline; later execution is liable to rejection.','Treasury / Bid Manager','Record portal execution timestamp and evidence; reconcile actual closing date with all extension notices.'),
('P9-02','Bid validity','Corrigendum_2.pdf pp1-2,5; Corrigendum_4.pdf p1; CQ_replies_BRRP.pdf pp2-3','Bid security extends 45 days beyond bid validity or extended validity. Bid validity is 120 days after opening of unpriced techno-contractual bids; do not anchor it to submission closing.','Treasury / Contracts','Use actual opening date; diarise bid and security expiry separately. Surety claim-period provisions remain distinct.'),
('P9-03','Performance security','Corrigendum_1_BRRP.pdf p1','The quoted ITB 28.1 option for 3% initial security plus 7% progressive deductions is deleted.','Contracts / Finance','Remove that financing assumption; reconcile remaining ITB 28.1, IFB and B-3 for governing amounts, submission and validity. Do not infer replacement wording from deletion alone.'),
('P9-04','Supporting-company guarantees','Corrigendum_2.pdf pp2-5','B-19/B-20/B-22 specified guarantee deadlines change from 15 to 30 days from NOA. Applicable supporting/JV guarantee provisions include delayed-submission recovery wording.','Contracts / Treasury','Set separate applicable-route milestones. Review 1.5% of performance-security amount per month or part-month recovery wording; do not apply indiscriminately to every guarantee.'),
('P9-05','Setting out and changes','Corrigendum_3.pdf p1, GCC 2.3.6','Modified column reinstates setting-out responsibility. Contractor corrects its positioning errors; company checking does not relieve it. Later company data/instructions after pre-engineering survey causing scope changes are dealt with under Clause 8.0.','Survey / Engineering / Contracts','Establish controlled datums, coordinates, survey acceptance and independent dimensional checks; preserve instruction/change evidence. This clause is not deleted.'),
('P9-06','Domestic steel compliance','Corrigendum_3.pdf pp1-8','DMI&SP policy reference changes to notification dated 17 December 2025, G.S.R.904(E). All bidders submit Form-1; item-specific Melt & Pour and domestic-value-addition provisions apply.','Procurement / QA / Contracts','Classify items under policy Appendix A/B and HS code. Obtain heat/mill origin records, Form-1, authorisations and applicable auditor certificates; maintain traceability. Do not confuse these policy appendices with tender appendices.'),
('P9-07','MSE and local content','CQ_replies_BRRP.pdf p5','ONGC reply says PPP-MSE exemption/purchase-preference benefits do not apply to this LSTK works tender. PP-MII is referred to ITB23.6.2(b).','Bid / Procurement','Remove assumed MSE EMD exemption; verify PP-MII separately, including current amendments.'),
('P9-08','Bid content','CQ_replies_BRRP.pdf p6','ONGC reply requires only BRS Part V-A with Quoted/Not Quoted confirmations in the unpriced bid; price manner follows the actual price format.','Bid Manager','Keep prices in the correct cover; reconcile all A-3 line items and BRS. This reply does not waive separate subcontractor commitment requirements.'),
('P9-09','Tax and precedence','CQ_replies_BRRP.pdf pp7-9','Beyond-12NM works are not declared tax-exempt: prevailing GST applies; offshore GSTIN may be used. SCC overrides GCC for conflicts; complete priority is referred to B-4. Liability reduction request was rejected.','Tax / Contracts','Prepare transaction-specific GST, customs and withholding matrix; use B-4 for full hierarchy. Do not adopt the bidder-proposed document hierarchy or 15% liability cap.'),
('P9-10','Pre-bid and extension requests','Corrigendum_1_BRRP.pdf p1; CQ_replies_BRRP.pdf pp7,9','Pre-bid conference was physical only, 8 April 2026. Six-week bid extension request was called premature at PBC stage.','Document Control / Bid','Record historical event; use issued extension notices for actual deadline. This reply is not a six-week extension grant.'),
('P9-11','Integrity pact','IP (1).pdf pp2,4-6; IP.pdf identical','Disclose intermediaries and relevant transgressions, obtain subcontractor adoption undertakings, retain records for IEM access. Contractor pact duration extends 12 months beyond last payment; other bidders six months after award, subject to outstanding claims.','Compliance / Contracts','Maintain signed pact, partner/consortium signatures as applicable, declarations and subcontract flow-down; extend compliance retention beyond physical completion. No signed compliance evidence established by blank form.'),
('P9-12','PPE','Kits PPE List-BRRP.pdf p1','Per person: 2 cotton overalls; 2 FR overalls; 2 pairs industrial shoes; 2 pairs electrical-hazard shoes for electrical personnel; 2 helmets; 2 clear goggles; 2 pairs ear muffs; 4 pairs impact/cut gloves; 2 pairs reusable ear plugs; 2 pairs rubber electrical gloves. Each construction season OR condition-based replacement.','HSE / Procurement','Cost against actual personnel and seasons; certified BIS/EN/ANSI items; issue before work, track replacement. Add task-specific PPE from HIRA/JSA/PTW and OISD-STD-155. Do not use 60 accommodation places as total workforce.'),
('P9-13','Vendor revision gap closed','Combined_Addendum_3.pdf pp261-341','Offshore Suggested Vendor List Rev12.3, as on 27 March 2026, now located. Prior missing-version finding is closed for this list.','Procurement / Document Control','Use Rev12.3 for revision reconciliation with the reference-only-list amendment. Product/location/status checks remain necessary; current external status not verified.'),
('P9-14','Vendor restrictions','Combined_Addendum_3.pdf p262','B1 quotation permitted subject to resolving hold reasons at PS submission; B3 and banned product entries prohibit order placement as stated. B2 rules and manufacturer-location undertakings also apply.','Procurement / QA','Record product, manufacturing location, hold category, evidence and disposition before PO release. Reference-only lists do not erase explicit bans.'),
('P9-15','Piping material selection','Combined_Addendum_3.pdf pp1-124; material specification 2008 Rev3','Piping material classes and component schedules are supplied. Index requires missing class sheets needed by approved P&IDs to be prepared using FS2004A for company approval.','Piping / Procurement','Develop surveyed line list, fluid/design pressure-temperature, material class and corrosion allowance; approve PMS, stress/support loads, isometrics and MTO before purchase. Do not apply every class to BRRP.'),
('P9-16','Welding and NDT','Combined_Addendum_3.pdf pp125-167; FS2009F Rev8 plus Duplex Annex1 Rev1','Welding/NDT specification and seven scanned duplex annex pages supplied; scanned annex OCR reviewed. Material- and joint-specific applicability is essential.','Welding Engineer / QA','Prepare applicability matrix, approved WPS/PQR and welder qualifications, NDT procedures/personnel/calibration, weld maps, consumable traceability and repair controls. Duplex qualification/testing can be a procurement predecessor where applicable; no blanket structural NDT percentage asserted.'),
('P9-17','Protective coating','Combined_Addendum_3.pdf pp168-245; FS2005 Rev9 dated12 December2022','Protective-coating specification is supplied. Selection depends on substrate, exposure, service temperature and approved system.','Coating / QA / Planning','Prepare coating-system schedule, surface preparation/inspection, environmental logs, application/DFT/curing and repair records. Quantify areas from verified MTO; allow curing and inspection before transport. Full system-by-system numerical compliance review remains open.'),
('P9-18','Bridge piping flexibility','Combined_Addendum_3.pdf pp246-260, piping criteria Rev4; clause5.3 p260','Bridge piping must account for differential platform movement under extreme storm conditions; assess temperature-range flexibility and required loops/supports.','Piping Stress / Structural','Coordinate bearing movements, piping forces, support stiffness and bridge/platform analyses; close iterative reactions before design release. Generic fire-system text is not proof every system is additional bridge scope.'),
('P9-19','Schedule impact','P9-03 to P9-18; Appendix C-8 previously reviewed','These inputs create real predecessors for security, material-origin evidence, PS/vendor disposition, qualification, coating and survey/change control. Prior illustrative network is not revalidated by this audit.','Planning Manager','Update package-specific procurement and DCI/MCI review logic, working-day calendars and offshore windows; recalculate CPM only after durations/resources are evidenced. Do not reuse earlier float as an approved forecast.'),
('P9-20','Remaining version controls','Combined_Addendum_1.pdf p1; P8 and P9 inventories','SVL12.3 found, but positive identification of the announced revised Technical SCC and revised A-3 still requires controlled-document reconciliation.','Document Control / Contracts','Link each governing revision to actual source and issue notice; preserve unresolved drawing revision conflicts and MTO discrepancies. Do not mark all historical inputs fully reconciled.')]
(p/'findings.json').write_text(json.dumps(findings,indent=2))
wb=Workbook();ws=wb.active;ws.title='Impact and Actions';ws.append(['ID','Topic','Source (PDF page)','Finding','Proposed owner','Required action','Status'])
for f in findings:ws.append(list(f)+['Open / not execution evidence' if f[0]!='P9-13' else 'Source version located; downstream checks open'])
w=wb.create_sheet('File Inventory');w.append(['File','Pages','SHA256','Previously supplied exact copies','Duplicate in this batch','Path'])
for r in inv:w.append([r['name'],r['pages'],r['sha256'],len(r['prior_matches']),r['batch_duplicate_of'],r['result']['path']])
w=wb.create_sheet('Addendum 3 Map');w.append(['PDF pages','Source','Review coverage'])
for row in [('1-124','Piping material specification2008 Rev3','Section indexed; class-by-class selection remains engineering work'),('125-160','Welding and NDT FS2009F Rev8','Requirements screening; detailed applicability remains open'),('161-167','Duplex welding Annex1 Rev1','Scanned pages OCR reviewed; use original for numerical application'),('168-245','Protective coating FS2005 Rev9','Cover OCR verified; font encoding affects text; full numeric system review open'),('246-260','Piping design criteria Rev4','Requirements screening including movement clause5.3'),('261-341','Offshore SVL12.3','Revision and important notes checked; individual bid-vendor selection not performed')]:w.append(row)
for s in wb:
 s.freeze_panes='A2';s.auto_filter.ref=s.dimensions
 for c in s[1]:c.font=Font(bold=True,color='FFFFFF');c.fill=PatternFill('solid',fgColor='17365D')
 for row in s.iter_rows(min_row=2):
  for c in row:c.alignment=Alignment(wrap_text=True,vertical='top')
 for col in s.columns:s.column_dimensions[col[0].column_letter].width=48 if col[0].column>2 else 25
wb.save(p/'BRRP_P9_Source_Impact_Register.xlsx')
doc=Document();doc.add_heading('BRRP — Review of latest uploaded documents',0)
doc.add_paragraph('P9 | 25 October 2026 | Tender ZW1PC26002 | Source review and required package updates')
unique={r['sha256']:r for r in inv};new=[r for r in inv if not r['prior_matches'] and not r['batch_duplicate_of']]
doc.add_paragraph(f"All {len(inv)} uploaded files were downloaded, opened and hash-checked: {len(unique)} distinct contents in this batch; {len(new)} new distinct contents versus prior local uploads, totalling {sum(r['pages'] for r in new)} new pages. Nine uploaded files match earlier local sources exactly; two further files duplicate another new/batch source. Duplicate files are retained in the inventory.")
doc.add_paragraph('This is an input and impact audit, not a claim that the entire engineering design, schedule or all historical documents have been fully validated. PDF page references below are one-based file pages. Bidder questions/proposals are distinguished from the reply column; no external messages, declarations, orders or approvals were issued.')
doc.add_heading('Most significant outcome',1);doc.add_paragraph('SVL Revision12.3 is now located in Combined Addendum3 pages261–341. This closes that specific previous missing-input finding. Commercial/security controls, steel-origin evidence, survey responsibility, PPE and discipline QA requirements require downstream updates. Earlier engineering and schedule deliverables remain development material, without AFC approval or a newly calculated critical path.')
for f in findings:
 doc.add_heading(f[0]+' — '+f[1],2);doc.add_paragraph('Source: '+f[2]);doc.add_paragraph(f[3]);doc.add_paragraph('Required update — '+f[5]);doc.add_paragraph('Proposed owner: '+f[4]+'. Completion evidence: not established by this source review.')
doc.add_heading('Review boundaries and next controlled issue',1)
doc.add_paragraph('Combined Addendum3 contains341 pages. Section boundaries and source revisions were checked. Fourteen selected pages were OCRed, including all seven low-text duplex annex pages and specification covers. Some piping/coating text has defective font encoding; no claim is made that every tabulated value has been verified. Numerical values must be read from the original relevant sheet during discipline design/QA review. SVL restrictions were screened, but every vendor/product entry was not individually evaluated.')
doc.add_paragraph('Required next issue: controlled requirement matrix → bridge-by-bridge scope/design/MTO reconciliation → vendor and procurement/QA package updates → DCI/MCI and review-calendar updates → resource and marine-window validation → recalculated CPM/cash flow → independent design check and company approvals. Actual site verification, qualification tests, accepted vendors, signed commitments and construction release remain execution/approval gates; templates do not establish that these gates passed.')
doc.save(p/'BRRP_P9_Latest_Document_Analysis.docx')
dest=pathlib.Path('/workspace/downloads');dest.mkdir(exist_ok=True)
for name in ['BRRP_P9_Latest_Document_Analysis.docx','BRRP_P9_Source_Impact_Register.xlsx']:
 shutil.copy2(p/name,dest/name);(dest/name).chmod(0o644)
assert len(load_workbook(p/'BRRP_P9_Source_Impact_Register.xlsx').worksheets)==3
assert len(Document(p/'BRRP_P9_Latest_Document_Analysis.docx').paragraphs)>100
print(json.dumps({'uploads':len(inv),'distinct':len(unique),'new_distinct':len(new),'new_pages':sum(r['pages'] for r in new),'findings':len(findings),'outputs':[str(dest/x) for x in ['BRRP_P9_Latest_Document_Analysis.docx','BRRP_P9_Source_Impact_Register.xlsx']]}))
